package middleware

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"9router/proxy/internal/db"
	"9router/proxy/internal/handlerutil"
)

const dashboardAuthCookie = "auth_token"

// DashboardJWTSecrets returns all configured HS256 secrets in priority order:
// <DATA_DIR>/jwt-secret (auto-generated by companion Next.js) and JWT_SECRET env.
// Checking both guarantees session interoperability even when Go loads a .env
// whose JWT_SECRET differs from a pre-started dashboard process.
func DashboardJWTSecrets(dataDir string) [][]byte {
	var secrets [][]byte
	seen := make(map[string]bool)
	add := func(s string) {
		s = strings.TrimSpace(s)
		if s != "" && !seen[s] {
			seen[s] = true
			secrets = append(secrets, []byte(s))
		}
	}
	if dataDir != "" {
		if raw, err := os.ReadFile(filepath.Join(dataDir, "jwt-secret")); err == nil {
			add(string(raw))
		}
	}
	add(os.Getenv("JWT_SECRET"))
	return secrets
}

// VerifyDashboardSession validates the companion Next.js dashboard auth_token
// cookie signed with HS256 using JWT_SECRET or <DATA_DIR>/jwt-secret.
func VerifyDashboardSession(r *http.Request, dataDir string) bool {
	c, err := r.Cookie(dashboardAuthCookie)
	if err != nil || c == nil || c.Value == "" {
		return false
	}
	secrets := DashboardJWTSecrets(dataDir)
	if len(secrets) == 0 {
		return false
	}

	parts := strings.Split(c.Value, ".")
	if len(parts) != 3 {
		return false
	}
	headerRaw, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return false
	}
	var hdr struct {
		Alg string `json:"alg"`
	}
	if err := json.Unmarshal(headerRaw, &hdr); err != nil || hdr.Alg != "HS256" {
		return false
	}

	sigBytes, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return false
	}
	sigValid := false
	signingInput := []byte(parts[0] + "." + parts[1])
	for _, secret := range secrets {
		mac := hmac.New(sha256.New, secret)
		_, _ = mac.Write(signingInput)
		if hmac.Equal(sigBytes, mac.Sum(nil)) {
			sigValid = true
			break
		}
	}
	if !sigValid {
		return false
	}

	payloadRaw, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return false
	}
	var claims struct {
		Exp int64 `json:"exp"`
	}
	if err := json.Unmarshal(payloadRaw, &claims); err != nil {
		return false
	}
	if claims.Exp > 0 && time.Now().Unix() >= claims.Exp {
		return false
	}
	return true
}

// MintLoopbackAuthTokens creates short-lived HS256 JWTs for each candidate
// dashboard secret so background automation can call internal dashboard endpoints.
func MintLoopbackAuthTokens(dataDir string) []string {
	secrets := DashboardJWTSecrets(dataDir)
	if len(secrets) == 0 {
		return nil
	}
	hdr := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
	now := time.Now().Unix()
	payloadBytes, _ := json.Marshal(map[string]any{
		"sub":  "9router-gateway",
		"role": "admin",
		"iat":  now,
		"exp":  now + 60,
	})
	payload := base64.RawURLEncoding.EncodeToString(payloadBytes)
	signingInput := hdr + "." + payload

	tokens := make([]string, 0, len(secrets))
	for _, secret := range secrets {
		mac := hmac.New(sha256.New, secret)
		_, _ = mac.Write([]byte(signingInput))
		sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
		tokens = append(tokens, signingInput+"."+sig)
	}
	return tokens
}

// RequireGatewayAuth authenticates administrative console/API requests using either:
//  1. A valid API key (Authorization: Bearer <key> or X-API-Key: <key>), or
//  2. An authenticated Next.js dashboard browser session cookie (auth_token).
func RequireGatewayAuth(repo *db.Repo, dataDir string) func(http.Handler) http.Handler {
	apiKeyCheck := RequireApiKey(repo)
	return func(next http.Handler) http.Handler {
		apiKeyProtected := apiKeyCheck(next)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if ExtractApiKey(r) != "" {
				apiKeyProtected.ServeHTTP(w, r)
				return
			}
			if VerifyDashboardSession(r, dataDir) {
				next.ServeHTTP(w, r)
				return
			}
			handlerutil.WriteJSONError(w, http.StatusUnauthorized, "Authentication required. Sign in to the Dashboard or provide an API key.")
		})
	}
}
